INSERT INTO m250_art VALUES
(0,0,$m250$الديباجة$m250$,$m250$قانون رقم 111 لسنة 1980 بإصدار قانون ضريبة الدمغة
باسم الشعب
رئيس الجمهورية
قرر مجلس الشعب القانون الآتى نصه ، وقد أصدرناه :$m250$,'119718bf0358c231f4d5a90ed804dc82'),
(1,-1,$m250$مادة 1 إصدار$m250$,$m250$يعمل بأحكام القانون المرافق بشأن ضريبة الدمغة .$m250$,'4de1e5f269b8a9bf2fbec45e8647a1d4'),
(2,-1,$m250$مادة 2 إصدار$m250$,$m250$يلغى القانون رقم 224 لسنة 1951 بتقرير رسم دمغة والقوانين المعدلة له .$m250$,'d61b391069e0d778d3e56c87623a5d15'),
(3,-1,$m250$مادة 3 إصدار$m250$,$m250$يصدر وزير المالية اللوائح والقرارات اللازمة لتنفيذ أحكام هذا القانون ، وإلى أن تصدر هذه اللوائح والقرارات يستمر العمل باللوائح والقرارات المعمول بها فيما لا يتعارض مع أحكام هذا القانون .$m250$,'9827bc8f68ae0e4057a21561e643ccf5'),
(4,-1,$m250$مادة 4 إصدار$m250$,$m250$ينشر هذا القانون فى الجريدة الرسمية ، ويعمل به من اليوم التالى لتاريخ نشره .$m250$,'ae1ca224d7e2797691b06d55d9fd8f82'),
(1,0,$m250$المادة 1$m250$,$m250$تفرض ضريبة دمغة على المحررات والمطبوعات والمعاملات والأشياء والوقائع وغيرها من الأوعية المنصوص عليها فى هذا القانون .$m250$,'d1db899c3d69793d39e93f8d8ab27370'),
(2,0,$m250$المادة 2$m250$,$m250$ضريبة الدمغة نوعان :
(أ) ضريبة دمغة نوعية .
(ب) ضريبة دمغة نسبية .$m250$,'3afd2f9a02663e25b84f38dc71bc6178'),
(3,0,$m250$المادة 3$m250$,$m250$تستحق الضريبة على المحررات من تاريخ تحريرها ودون نظر الى صحتها . على أنه بالنسبة الى الحالتين الآتيتين يكون استحقاق الضريبة على المحررات عند استعمالها بعد العمل بأحكام هذا القانون :
(أ) اذا كانت محررة قبل 15/5/1939 تاريخ العمل بالقانون رقم 44 لسنة 1939 بتقرير رسم دمغة .
(ب) اذا كانت محررة فى الخارج واستعملت فى الجمهورية .
ويقصد بالاستعمال استخدام المحرر ذاته مباشرة فى أى عمل من شأنه أو يقصد به انتاج أثر من الآثار القانونية .
ويتحمل المستعمل الضريبة .
ولا ترد الضريبة مهما تكن الأسباب التى تجعل المحررات عديمة الأثر .$m250$,'0f8ce7b38ab137ab3abda9fae9d6b063'),
(4,0,$m250$المادة 4$m250$,$m250$تستحق الضريبة على غير المحررات من الوقائع والمعاملات من تاريخ تحققها ، وعلى الأشياء من تاريخ اعدادها الاعداد الذى تقتضيه طبيعتها والغرض منها .$m250$,'4999acad77603ab219f11b19b4d0fa30'),
(5,0,$m250$المادة 5$m250$,$m250$لا يجوز الاتفاق على ما يخالف الأحكام الواردة فى هذا القانون بالنسبة الى من يتحمل بعبء الضريبة .$m250$,'70a90e11101a7b367d3ab07bd3724e7f'),
(6,0,$m250$المادة 6$m250$,$m250$على أصحاب الشأن أن يضمنوا المحرر قيمة التعامل فى الأحوال التى يتوقف تحديد الضريبة فيها على هذه القيمة ، فاذا لم يتضمن المحرر قيمة التعامل ، أو رأت مصلحة الضرائب أن القيمة المذكورة فيه أو فى الاخطار الذى تؤدى بموجبه الضريبة تقل بمقدار يزيد على عشر القيمة الحقيقية فللمصلحة أن تقدر هذه القيمة وفقا لما يتكشف لها من أدلة وقرائن .
وعلى المصلحة اخطار الممول بالتقدير بكتاب موصى عليه مصحوب بعلم الوصول فاذا لم يتظلم الممول من التقدير خلال ثلاثين يوما من تاريخ تسلمه للاخطار يكون الربط نهائيا وتصبح الضريبة واجبة للأداء وفقا لتقدير المصلحة .
وللممول فى حالة عدم موافقته على هذا التقدير أن يتظلم منه بكتاب موصى عليه مصحوب بعلم الوصول الى المأمورية المختصة لاحالته الى لجنة الطعن المنصوص عليها فى المادة 50 من القانون رقم 14 لسنة 1939 وذلك خلال ثلاثين يوما من تاريخ تسلمه للاخطار بالتقدير .
وعلى الممول سداد الضريبة وفقا لقرار اللجنة الصادر فى هذا الشأن بمجرد تسلمه للتنبيه بالسداد من مأمورية الضرائب المختصة .
وللممول أن يطعن فى قرار اللجنة بدعوى أمام المحكمة الابتدائية التى يقع فى دائرتها وذلك خلال ثلاثين يوما من تاريخ تسلمه للقرار .
ولا يوقف الطعن أمام المحكمة وجوب أداء الضريبة .
ويكون ميعاد استئناف الأحكام الصادرة من المحاكم الابتدائية فى المنازعات المشار اليها فى هذه المادة أربعين يوما من تاريخ اعلان الحكم .$m250$,'bdbca645634d0a634863c67ae782b81e'),
(7,0,$m250$المادة 7$m250$,$m250$تتعدد الضريبة بتعدد الأحكام فى المحرر الواحد ما لم يرد نص على خلاف ذلك فى هذا القانون .
ويقصد بالحكم كل موضوع له ذاتية مستقلة يصلح كوعاء للضريبة طبقا لأحكام هذا القانون .$m250$,'e2049264645697ca30abd905a30d028a'),
(8,0,$m250$المادة 8$m250$,$m250$اذا كان المحرر من عدة نسخ أو صور ممضاه استحقت على كل نسخة أو صورة الضريبة التى تستحق على الأصل فيما عدا الضريبة النسبية فلا تحصل الا مرة واحدة على الأصل وذلك ما لم ينص القانون على خلاف ذلك .
وتعتبر الصورة الفوتوغرافية فى حكم النسخة أو الصورة الممضاه فى حالة استعمالها على الوجه المشار اليه فى المادة (3) من هذا القانون .$m250$,'17376316d8f30cd1a24d659f33f825d8'),
(9,0,$m250$المادة 9$m250$,$m250$لا تستحق الضريبة على صور الأوراق التجارية ولا نسخها اذا قدمت مرفقة بالأصل المدفوعة عنه الضريبة .$m250$,'591997ef8e15797b719997d82ba62646'),
(10,0,$m250$المادة 10$m250$,$m250$تحدد مصلحة الضرائب الضريبة المستحقة غير المؤداة وفقا لما يتكشف لها من الاطلاع أو المعاينة .
وللمصلحة كذلك تقدير الضريبة المستحقة وفقا لما يتبين لها من الأدلة والقرائن وذلك عند الامتناع عن تقديم المحررات والمستندات للاطلاع ، أو اتلافها قبل انقضاء أجل التقادم المسقط لاقتضاء الضريبة والمنصوص عليه فى هذا القانون .
ويعلن الممول بالضريبة أو فروقها بكتاب موصى عليه بعلم الوصول مبينا به المحررات أو الوقائع أو التصرفات أو غيرها التى استحقت عليها الضريبة أو فروقها .
وتسرى فى هذه الحالة اجراءات تقدير قيمة المعاملات والطعن فيه المنصوص عليها فى المادة 6 من هذا القانون .$m250$,'00e970dae431b6cd28a7e35b3bac73a1'),
(11,0,$m250$المادة 11$m250$,$m250$يراعى فى تحديد وتحصيل الضريبة المستحقة جبر كسور القرش الى قرش .$m250$,'fabed96202539e22790719b5e8057873'),
(12,0,$m250$المادة 12$m250$,$m250$لا تسرى الضريبة على المعاملات التى تجرى بين الجهات الحكومية أو بينها وبين شخص معفى من الضريبة .
واذا كان التعامل بين جهة حكومية وشخص غير معفى من الضريبة فيتحمل هذا الشخص كامل الضريبة المستحقة على التعامل .
على أنه فى حالة تعدد النسخ أو الصور التى تحتفظ بها الجهة الحكومية لدواعى العمل بها فلا يتحمل المتعامل معها سوى الضريبة المستحقة على نسخة أو صورة واحدة من تلك النسخ أو الصور .
ويعفى من الضريبة أوراق حركة النقود المملوكة للحكومة .$m250$,'b2addb3ce5b20d5be94b2dadf6f6227c'),
(13,0,$m250$المادة 13$m250$,$m250$فى حالة بيع وشراء الأوراق المالية لا يتحمل المتعامل مع الجهة الحكومية سوى الضريبة التى يقع عبؤها عليه .$m250$,'cf8b8a6f6444177cbf3b55cb91eef071'),
(14,0,$m250$المادة 14$m250$,$m250$يقصد بالجهات الحكومية فى تطبيق أحكام هذا القانون :
(أ) وزارات الحكومة ، ومصالحها ، والأجهزة التى لها موازنة خاصة بها .
(ب) وحدات الحكم المحلى .
(ج) الهيئات العامة .
(د) المجالس العليا للقطاعات لشركات القطاع العام .$m250$,'f8c40a072846aac156f29821b096c1f6'),
(15,0,$m250$المادة 15$m250$,$m250$تؤدى ضريبة الدمغة باحدى الطرق الآتية :
(أ) استعمال النماذج المدموغة مقدما والتى تعدها مصلحة الضرائب للمحررات التى يعينها ويحدد بياناتها وثمنها قرار من رئيس المصلحة المذكورة على ألا يجاوز هذا الثمن قيمة الضريبة المستحقة وتكاليف اعداد المحرر .
(ب) استعمال النماذج التى تعدها الجهات صاحبة الشأن للمحررات الخاصة بها وتقدمها الى مصلحة الضرائب لدمغها قبل استعمالها .
(ج) الصاق طوابع الدمغة .
ويجب الغاء طوابع الدمغة فور لصقها وبمعرفة من يلصقها وذلك على الوجه المبين فى اللائحة التنفيذية .
(د) ختم المحررات بأختام الدمغة التى تعدها مصلحة الضرائب لهذا الغرض .
(هـ) أية طريقة أخرى تبين فى اللائحة التنفيذية .$m250$,'d78d63820a69fa12e0acb8cb76847238'),
(16,0,$m250$المادة 16$m250$,$m250$تؤدى الضريبة على ايصالات سداد أجرة العقارات الخاضعة للضريبة على العقارات المبنية أو ضريبة الدفاع أو ضريبة الأمن القومى نقدا مع تلك الضرائب وبذات اجراءات ومواعيد تحصيلها .
ويفترض تحرير ايصالات سداد أجرة العقارات المشار اليها شهريا ما لم يثبت عكس ذلك .$m250$,'974f23df4c2c3351bac0814d9ee4aaa6'),
(17,0,$m250$المادة 17$m250$,$m250$تحصل الضرائب والغرامات والتعويضات المستحقة طبقا لأحكام هذا القانون فى حالة الامتناع عن سدادها طبقا لأحكام قانون الحجز الادارى .
ويكون لمصلحة الضرائب حق امتياز على جميع أموال المدينين بالمبالغ المذكورة والملزمين بتوريدها للخزانة طبقا لأحكام هذا القانون .$m250$,'252a93b523525a67422f574417464440'),
(18,0,$m250$المادة 18$m250$,$m250$يعتبر موظفو مصلحة الضرائب الذين يصدر بتحديد وظائفهم قرار من وزير العدل بالاتفاق مع وزير المالية من مأمورى الضبط القضائى فيما يتعلق بتنفيذ أحكام هذا القانون والقرارات الصادرة تنفيذا له .$m250$,'6c0148c46540a881f52ea3ca22571fcd'),
(19,0,$m250$المادة 19$m250$,$m250$يكون لمأمورى الضبط القضائى المشار اليهم حق الاطلاع لدى الجهات الحكومية وغيرها من أشخاص القانون العام والخاص والممولين بصفة عامة على كافة المحررات والمستندات والوثائق والدفاتر والسجلات وغيرها مما يتطلب الاطلاع أو المعاينة ، ولا يجوز منعهم من الاطلاع ولو بسبب المحافظة على سر المهنة .
ويجرى الاطلاع فى مقر نشاط الممول أثناء ساعات العمل ، وعلى مأمور الضبط القضائى اثبات ما يتم ، ويتكشف له من مخالفات فى محضر محرر وفقا لما تقرره اللائحة التنفيذية .$m250$,'08156fe93743c51c9c5a6bff6e1b2ae2'),
(20,0,$m250$المادة 20$m250$,$m250$كل شخص له بحكم وظيفته أو اختصاصه أو عمله شأن فى ربط أو تحصيل الضرائب المنصوص عليها فى هذا القانون أو فى الفصل فيما يتعلق بها من المنازعات ملزم بمراعاة سر المهنة ، ويعاقب كل من يخالف ذلك بالعقوبات المنصوص عليها فى قانون العقوبات .$m250$,'c0d921be67ec81fde8d3a31f3ca43d03'),
(21,0,$m250$المادة 21$m250$,$m250$يحظر التعامل فى وعاء من الأوعية الخاضعة لضريبة الدمغة ما لم تكن الضريبة المستحقة على ذلك الوعاء مسددة بالكامل .$m250$,'bff55c34277637990bc69f6971760ac4'),
(22,0,$m250$المادة 22$m250$,$m250$لا يجوز للقضاة وغيرهم من الموظفين العموميين اصدار أحكام أو قرارات أو وضع اشارات أو التصديق على امضاءات أو القيام بأى عمل مما يدخل فى اختصاصاتهم ما لم تكن ضريبة الدمغة المستحقة بمقتضى هذا القانون قد أديت فعلا .
ويجب ضبط كل محرر مما يقع تحت أيديهم لم تؤد عنه الضريبة المستحقة ، وعليهم طلب استيفائها فاذا رفض ذو الشأن أداء الضريبة تعين ابلاغ مصلحة الضرائب ، ولا يسلم المحرر أو الشىء المضبوط لصاحبه الا اذا أديت الضريبة المستحقة عليه ولو كان عبؤها واقعا على غيره .
ولا تسرى أحكام هذه المادة على الايصالات المشار اليها فى المادة 16 .$m250$,'4fff57b644fbd00e17f9d237fca2a759'),
(23,0,$m250$المادة 23$m250$,$m250$كل محرر لم تؤد الضريبة المستحقة عليه طبقا لأحكام هذا القانون وكذلك كل حكم يصدر أو عمل رسمى يتم خلافا لأحكام المادة السابقة يجب عند تنفيذه أو التمسك به أن تؤدى عنه الضريبة المستحقة . وذلك دون اخلال بحق مصلحة الضرائب فى اقتضاء الغرامات والتعويضات المقررة قانونا .$m250$,'c71577c6afb7e88e6bc61ea27078c3fa'),
(24,0,$m250$المادة 24$m250$,$m250$لا تسرى أحكام المادتين السابقتين فى المواد الجنائية ولا فى مسائل الجرد والحصر التى تباشرها سلطات رسمية .
وكذلك يجوز للقضاة فى الأحوال المستعجلة أن يأمروا باتخاذ اجراءات وقتية مع عدم الاخلال باستحقاق الضريبة وتحصيلها .$m250$,'d42e8fcfb311b11b04c46a3f1017d10f'),
(25,0,$m250$المادة 25$m250$,$m250$يسقط حق الخزانة فى المطالبة بأداء الضرائب والتعويضات والغرامات المستحقة طبقا لأحكام هذا القانون بمضى خمس سنوات تبدأ من تاريخ الاستحقاق .
على أنه اذا ثبت اخفاء الممول للأوعية الخاضعة للضريبة فلا يبدأ التقادم الا من تاريخ كشف الاخفاء وضبط الوعاء .
وينقطع التقادم باجراءات المطالبة بأداء الضريبة .$m250$,'b7c308ded4bac5ccd0a527bd233721ff'),
(26,0,$m250$المادة 26$m250$,$m250$يسقط حق الممول فى المطالبة برد المبالغ المسددة كضرائب بدون وجه حق بمضى خمس سنوات من يوم أدائها .
ولا تقبل لأى سبب من الأسباب أية مطالبة برد قيمة طوابع الدمغة ولا النماذج المدموغة مقدما التى شرع فى الكتابة عليها كما لا يجوز استعمال تلك النماذج لمحرر آخر .$m250$,'d21329b13f894b74983e57285380ad72'),
(27,0,$m250$المادة 27$m250$,$m250$لا تخضع للضريبة الجهات الآتية :
(أ) هيئات التمثيل السياسى والقنصلى الأجنبية بشرط المعاملة بالمثل .
(ب) الهيئات الدولية .$m250$,'8a627e4d1f7a4b106882040a99e3f788'),
(28,0,$m250$المادة 28$m250$,$m250$لا تخل أحكام هذا القانون بأحكام القوانين الخاصة التى تقرر الاعفاء من الضريبة أو تحديد سعرها أو من يقع عليه عبؤها أو غير ذلك من الأحكام على خلاف ما هو منصوص عليه فى هذا القانون .$m250$,'008b0c1c9cc07950b85afd60c3868c81'),
(29,0,$m250$المادة 29$m250$,$m250$يعاقب على الامتناع عن تقديم المحررات وغيرها أو اتلافها قبل انقضاء مدة التقادم المنصوص عليها فى المادة 25 بغرامة لا تقل عن عشرة جنيهات ولا تزيد على مائتى جنيه وذلك دون اخلال بحق مصلحة الضرائب فى تقدير الضريبة المستحقة واقتضائها وفقا لأحكام هذا القانون .
ويعتبر امتناعا عدم تقديم المحررات بعد مضى ثلاثين يوما على اخطار الممول بوجوب تقديمها بمقتضى خطاب موصى عليه مصحوب بعلم الوصول .$m250$,'239355fc0f2ed02332075cc7b1437c3e'),
(30,0,$m250$المادة 30$m250$,$m250$يعاقب بالحبس مدة لا تجاوز ستة شهور وبغرامة لا تقل عن خمسين جنيها ولا تجاوز مائة وخمسين جنيها أو باحدى هاتين العقوبتين :
(أ) كل من صنع مطبوعات أو نماذج مهما تكن طريقة صنعها تشابه بهيئتها الظاهرة علامات وأختام وطوابع مصلحة الضرائب بدلا من المطبوعات والنماذج الصحيحة .
كما يعاقب بذات العقوبات كل من وزع أو عرض للبيع تلك المطبوعات والنماذج مع علمه بذلك .
(ب) كل من تعمد من موظفى الحكومة وغيرهم اساءة استعمال أختام دمغة الضرائب بطريقة من شأنها ضياع حق على خزانة الدولة .$m250$,'97548b882dcb6c6e2e2a0b09a4f30b68'),
(31,0,$m250$المادة 31$m250$,$m250$يعاقب بالحبس مدة لا تجاوز ستة شهور وبغرامة لا تقل عن عشرة جنيهات ولا تجاوز خمسين جنيها أو باحدى هاتين العقوبتين :
(أ) كل من باع أو شرع فى بيع طوابع دمغة سبق استعمالها مع علمه بذلك .
(ب) كل من استعمل طوابع دمغة سبق استعمالها مع علمه بذلك .
وفى جميع الأحوال يكلف المخالف بلصق طوابع دمغة سليمة تعادل قيمة الطوابع المعاد استعمالها .$m250$,'8475f16391ad4ce5d9de17370234178f'),
(32,0,$m250$المادة 32$m250$,$m250$يعاقب بغرامة لا تقل عن خمسة جنيهات ولا تجاوز عشرة جنيهات كل من باع أو عرض للبيع طوابع الدمغة أو الاستمارات أو النماذج المدموغة مقدما بسعر يزيد على السعر المقرر لها .$m250$,'dad24c4cf15f215a6d9f8f227db01284'),
(33,0,$m250$المادة 33$m250$,$m250$يعاقب بغرامة لا تقل عن جنيه ولا تجاوز خمسة جنيهات كل من ارتكب أحد الأفعال الآتية :
(أ) توقيع أو قبول أو استعمال عقد أو محرر أو غيره لم تؤد عنه الضريبة المستحقة .
(ب) التوسط فى التعامل أو فى تحصيل قيمة سندات أو أوراق تجارية أو أى محرر لم تؤد عنه الضريبة المستحقة .
ويحكم بالغرامة فى الأحوال المنصوص عليها فى البندين أ ، ب عن كل عقد أو محرر أو اعلان أو غيره وجد على خلاف أحكام هذا القانون .
(ج) أية مخالفة لأحكام هذا القانون والقرارات الصادرة تنفيذا له .$m250$,'be5ca9a763d56f2b8a77b08bf4db7704'),
(34,0,$m250$المادة 34$m250$,$m250$يعاقب على مخالفة أحكام المادة 23 بغرامة لا تقل عن عشرة جنيهات ولا تزيد على خمسين جنيها .$m250$,'4fa3a9b85ea948a81d46f71b09f709b1'),
(35,0,$m250$المادة 35$m250$,$m250$علاوة على العقوبات الأخرى المنصوص عليها فى هذا القانون يحكم القاضى على كل من اشتركوا فى الجريمة بأداء المبالغ الآتية بالتضامن فيما بينهم .
(أ) قيمة الضرائب المستحقة والتى لم تسدد .
(ب) تعويض للخزانة العامة لا يقل عن خمسة أمثال الضرائب غير المؤداة ولا يزيد على عشرة أمثالها .$m250$,'9cf93ef2427c637625524672e12da5dc'),
(36,0,$m250$المادة 36$m250$,$m250$يعفى من المسئولية الجنائية والتضامن فى أداء الجزاءات المنصوص عليها فى المادة السابقة من أبلغ مصلحة الضرائب ممن لا يقع عليهم عبء الضريبة عن وقوع المخالفة فى مدى ثلاثين يوما من تاريخ وقوعها .$m250$,'c5f779ea5a9f09dd28ab9dace128f405'),
(37,0,$m250$المادة 37$m250$,$m250$لا تحال الجرائم المنصوص عليها فى هذا القانون الى النيابة العامة الا بقرار من وزير المالية أو من ينيبه ، ولا ترفع الدعوى الجنائية الا بناء على طلبه .
ويجوز لوزير المالية حتى تاريخ رفع الدعوى الجنائية الصلح مع الممول على أساس أداء الضريبة المستحقة علاوة على دفع مبلغ يعادل مثلى ضريبته النسبية وثلاثة أمثال الضريبة النوعية التى لم تؤد فى مقابل التنازل عن رفع الدعوى الجنائية .
كما يكون لوزير المالية الصلح بعد رفع الدعوى وقبل صدور حكم نهائى على أساس دفع قيمة الضريبة المستحقة علاوة على مبلغ يعادل ثلاثة أمثال الضريبة النسبية وخمسة أمثال الضريبة النوعية التى لم تؤد .
وتنقضى الدعوى الجنائية بالصلح .$m250$,'9d17c2861de92ca1d9066a89c6635e04'),
(38,0,$m250$المادة 38$m250$,$m250$تلتزم الجهات المكلفة قانونا بتحصيل الضريبة من الممولين وتوريدها الى مصلحة الضرائب بأداء مقابل تأخير مقداره ستة فى المائة سنويا من قيمة الضريبة اللازمة بتوريدها .
ويسرى ذلك من اليوم التالى للمواعيد المحددة للتوريد فى هذا القانون أو لائحته التنفيذية مع اعتبار كسور الشهر شهرا كاملا .
ولا يستحق المقابل اذا لم تجاوز مدة التأخير سبعة أيام .$m250$,'4d93bfa67e3f7db9bfb1bb5b5012d86d'),
(39,0,$m250$المادة 39$m250$,$m250$تستحق ضريبة نوعية على الشهادات الدراسية المبينة فيما يلى وما يعادلها بالفئات الموضحة قرين كل منها :
الشهادة الابتدائية ...... مائتا مليم
الشهادة الاعدادية بأنواعها ...... ثلاثمائة وخمسون مليما
الشهادة الثانوية بأنواعها ...... خمسمائة مليم
شهادة الليسانس أو البكالوريوس ...... جنيه
دبلومات الدراسات العليا ...... جنيهان
شهادة الماجستير ...... ثلاثة جنيهات
شهادة الدكتوراه ...... خمسة جنيهات
ولايسرى هذا النص على الشهادات والاقرارات المؤقتة بالحصول على المؤهل الدراسى .$m250$,'a50d9ca8279e93570e4b0f3f95958342'),
(40,0,$m250$المادة 40$m250$,$m250$تخضع الشهادات الآتية لضريبة نوعية مقدراها مائة وخمسون مليما عن كل ورقة من أوراقها .
أولا : جميع أنواع الشهادات الصادرة من الجهات الحكومية ، عدا الشهادات المشار اليها فى المادة السابقة .
ثانيا : الشهادات الصادرة من :
(1) الغرف التجارية أو الزراعية أو الصناعية أو السياحية .
(2) النقابات والاتحادات المهنية .
(3) الهيئات والمؤسسات والجمعيات الرياضية والاجتماعية .
(4) مخازن الايداع .
(5) وحدات التعاون الاستهلاكى والانتاجى .
(6) أية منشأة تجارية أو صناعية .
ثالثا : الشهادات المصدق على التوقيعات فيها بمعرفة جهة حكومية أو شركة قطاع عام ، وكذلك الاقرارات المقدمة من أصحاب الشأن الى أية جهة .
وفى جميع الأحوال يتحمل الضريبة مستلم الشهادة ، أو مقدم الاقرار ويعفى من الضريبة شهادة قيد العاطلين .$m250$,'9e8d04bb5fbb95513ad51c09c8bee6ef'),
(41,0,$m250$المادة 41$m250$,$m250$تستحق ضريبة نوعية مقدارها مائة وخمسون مليما عن كل ورقة من أوراق كل مستخرج أو صورة من العقود والوثائق والسجلات والدفاتر أو من أى محرر آخر لدى الجهات الحكومية والمنشآت التى تقوم بعمل تجارى أو صناعى أو زراعى .
وتسرى الضريبة على الصور الفوتوغرافية الصادرة من تلك الجهات والمعتمدة منها .
ويتحمل الضريبة مستلم الصور أو المستخرج .
ويعفى من الضريبة الصورة أو المستخرج الذى يسلم لأول مرة لأصحاب الشأن فى أحوال الميلاد والتطعيم والوفاة .$m250$,'1804e9c4bab7fcbf5375d1fe591e7e5e'),
(42,0,$m250$المادة 42$m250$,$m250$تستحق ضريبة نوعية مقدارها مائة وخمسون مليما عن كل ورقة من أوراق الطلبات والشكاوى الآتى بيانها :
(أ) الطلبات والشكاوى التى تقدم بقصد الحصول على خدمة أو مزية أو منفعة الى الجهات الآتية :
1 - الجهات الحكومية .
2 - شركات القطاع العام بشرط أن يكون الطلب أو الشكوى مقدمة من أحد العاملين بها .
3 - شركات القطاع الخاص التى يزيد رأسمالها على خمسة آلاف جنيه بشرط أن يكون الطلب أو الشكوى من أحد العاملين بها .
(ب) طلبات التوظيف التى تقدم الى الشركات المشار اليها فى البند السابق .
ويتحمل الضريبة مقدم الطلب أو الشكوى .$m250$,'170aaa09e9df3eb48460a7b43146aaec'),
(43,0,$m250$المادة 43$m250$,$m250$يعفى من الضريبة الطلبات والشكاوى الآتية :
(1) الشكاوى التى تقدم الى الشرطة أو النيابة العامة أو النيابة الادارية .
(2) الشكاوى المقدمة فى مسائل الضرائب .
(3) الشكاوى التى تقدم الى مرافق المياه والكهرباء والنقل والمواصلات السلكية واللاسلكية والموانى فيما يتعلق بالخدمة التى تقوم عليها تلك المرافق .
(4) استعجالات الطلبات والشكاوى المسدد عنها الضريبة المستحقة .
(5) الاستفسارات التى ترد للجهات المشار اليها فى المادة السابقة عن بعض المسائل التى تدخل فى اختصاصها .
(6) الطلبات والشكاوى المعفاة فعلا قبل العمل بهذا القانون .
(7) الطلبات والشكاوى التى يصدر قرار من وزير المالية باعفائها من الضريبة لاعتبارات صحية أو اجتماعية أو انسانية .$m250$,'d6efe30d8e3d88d3f612fe6a000b9928'),
(44,0,$m250$المادة 44$m250$,$m250$تستحق ضريبة نوعية مقدراها مائة وخمسون مليما عن كل ورقة من أوراق العقد أو الاشهاد وذلك بالنسبة الى جميع العقود بعوض أو بغير عوض ، مدنية كانت أو تجارية ولو تمت بالمراسلة ، وكذلك الاشهادات الخاصة بالوقف .
على أنه بالنسبة الى العقود التى تخضع طبقا لأحكام هذا القانون لضريبة معينة فلا يحصل عنها الا هذه الضريبة وحدها .
وتستحق الضريبة على العقد الشفوى عند التمسك به أمام القضاء وثبوت وجوده .$m250$,'6416b48c080c216316e9550c2a975cb7'),
(45,0,$m250$المادة 45$m250$,$m250$يتحمل كل متعاقد الضريبة المستحقة على النسخة أو النسخ أو الصورة أو الصور الخاصة به .
فاذا كان العقد من نسخة واحدة تحمل المتعاقدون الضريبة بالتساوى بينهم ما لم يكن أحدهم معفى قانونا فيتحمل الباقون بالتساوى الضريبة المستحقة بالكامل .
على أنه بالنسبة لعقد الوكالة يتحمل الضريبة الموكل .
واذا كان عقد الوكالة محررا على ظهر اذن الصرف الحكومى أو الورقة التجارية فيعفى العقد فى هذه الحالة من الضريبة .$m250$,'75957f47ca6e9c7ae30de05bdc5eefcc'),
(46,0,$m250$المادة 46$m250$,$m250$تستحق الضريبة بالنسبة الى عقود الزواج والطلاق على النحو التالى :
(1) جنيه ونصف على كل عقد زواج .
(2) جنيه واحد على كل وثيقة طلاق .
ويتحمل الزوج عبء الضريبة على عقود الزواج .
ويتحمل المطلق الضريبة على وثائق الطلاق .$m250$,'954fc692160e9f6808398f4a6719591b'),
(47,0,$m250$المادة 47$m250$,$m250$تستحق ضريبة نوعية مقدارها مائة وخمسون مليما عن كل ورقة من أوراق وثائق الملاحة التجارية كمحاضر المعاينة والشهادات المتعلقة بالبضائع المشحونة أو المفرغة واقرارات التلف وغيرها من الوثائق .
ويتحمل الضريبة مستلم الوثيقة .$m250$,'15f7ef13443a20738a3f6967c3dff46a'),
(48,0,$m250$المادة 48$m250$,$m250$تستحق ضريبة نوعية مقدراها مائة وخمسون مليما عن كل ورقة من أوراق محاضر انعقاد مجالس الادارة ومجالس المراقبة ، والجمعيات العمومية العادية وغير العادية لشركات المساهمة والتوصية بالأسهم ، والمسئولية المحدودة .
وتتحمل الشركة الضريبة .$m250$,'9a9ec54ad98f9e51544428d2b18da534'),
(49,0,$m250$المادة 49$m250$,$m250$تستحق ضريبة نوعية مقدارها مائة وخمسون مليما عن كل ورقة من أوراق المحررات القضائية الآتية :
(1) الأوامر بتنفيذ الأحكام الأجنبية فى مصر .
(2) الأوامر على العرائض التى يصدرها القضاة فى حدود سلطاتهم الولائية .
(3) كل نشرة قضائية عدا ما كان منها خاصا بالبيوع الجبرية .
ويتحمل الضريبة مستلم الأمر أو من عملت النشرة لصالحه .$m250$,'ce89b92bf956ad03b0fb40b4cffb2202'),
(50,0,$m250$المادة 50$m250$,$m250$تستحق ضريبة نسبية على أقساط ومقابل التأمين على النحو التالى :
(1) واحد ونصف فى المائة على كل قسط من أقساط التأمين على الحياة أو التأمين من الأمراض ، أو الاصابات الجسدية ، أو المسئولية المدنية المتعلقه بها ، وعنى اقساط التأمين الاجبارى أيا كان نوعه .
(2) سبعة ونصف فى المائة بحد أدنى عشرون مليما على مقابل التأمين على النقل البرى والنهرى والبحرى والجوى .
(3) عشرة فى المائة على كل قسط من أقساط التأمينات الأخرى ، وكذلك على مقابل هذه التأمينات بما فى ذلك التأمين ضد أخطار الحرب .
(4) اثنان فى المائة على رأس المال المبين فى عقود ترتيب ايراد لمدى الحياة أو لمدة محدودة .
(5) أربعة فى الألف سنويا على اجمالى مقابل وأقساط التأمين التى تحصلها شركات التأمين .$m250$,'2a5e1cbf150bd56009f5db9398032b32'),
(51,0,$m250$المادة 51$m250$,$m250$يتحمل الضريبة المستحقة على أقساط ومقابل التأمين كل من المؤمن والمؤمن له مناصفة .
وبالنسبة لعقود ترتيب الايراد يتحمل الضريبة المنتفع الا اذا كان ترتيب الايراد بمقابل فيتحمل المتعاقدان الضريبة مناصفة .
وتتحمل شركة التأمين عبء الضريبة على اجمالى أقساط ومقابل التأمين .
وفى جميع الأحوال لا تسرى الضريبة على أقساط ومقابل اعادة التأمين .$m250$,'707106c903a8b0767749b0868d138eeb'),
(52,0,$m250$المادة 52$m250$,$m250$تستحق ضريبة نسبية مقدارها ثلاثة فى الألف بحد أدنى ستون مليما على الكمبيالات والسندات تحت الاذن أو لحاملها .
ويتحمل الضريبة على الكمبيالات صاحب الكمبيالة وعلى السندات تحت الاذن مصدر السند .$m250$,'d41686c513c110de26b35744b1750151'),
(53,0,$m250$المادة 53$m250$,$m250$تستحق ضريبة نوعية مقدارها خمسون مليما على الشيكات بكافة أنواعها وأيا كانت قيمتها .
ويتحمل الضريبة الساحب .$m250$,'69efbd888309e487ac0ceae80c960c79'),
(54,0,$m250$المادة 54$m250$,$m250$تستحق ضريبة نوعية مقدارها خمسون مليما عن كل ايصال أو مخالصة أو فاتورة مؤشر عليها بالتخليص عما لاتقل قيمته عن مائة قرش .$m250$,'b62fa355c525d5c39d6add9f0ba5478a'),
(55,0,$m250$المادة 55$m250$,$m250$يتحمل الضريبة :
(1) من يسلم الايصال أو المخالصة .
(2) بالنسبة لايصالات المرتبات والأجور والاعانات : رب العمل أو الملتزم بأداء المرتب أو الأجر أو الاعانة .
(3) مستلم الفاتورة .$m250$,'e7eae2e9669a7373f803ef511314e127'),
(56,0,$m250$المادة 56$m250$,$m250$يعفى من الضريبة :
(1) الايصالات الخاصة بالمبالغ التى تودع بصناديق التوفير أو تسحب منها .
(2) الايصالات الداخلية المتبادلة بين موظفى المنشأة الواحدة أو أقسامها أو بينها وبين فروعها بشرط أن تكون بقصد تنظيم العمل الداخلى .
(3) الايصالات الصادرة من جهة حكومية باستلام شيك أو حوالة بريدية .
(4) الفواتير المتبادلة بين السماسرة فيما يتعلق بعمليات بيع وشراء الأوراق المالية .
(5) الايصالات التى تعطى عن المبالغ التى تودع البنوك لحساب من قام بالايداع أو لحساب شخص آخر .
(6) الايصالات التى تعطى من البنوك عن الأوراق المالية ( أسهم وسندات ) ، والأوراق التجارية ( شيكات وكمبيالات وسندات تحت الاذن ) التى تسلم للبنك على ذمة التحصيل أو القبول أو الرهن .$m250$,'1ada07aa347a272108a397cf0b98eab8'),
(57,0,$m250$المادة 57$m250$,$m250$تستحق الضريبة النسبية على الأعمال والمحررات المصرفية على الوجه الآتى :
(1) فتح الاعتماد :
خمسة فى الألف على عقود وعمليات فتح الاعتماد وكذلك على تجديدها بشرط ألا يكون الاعتماد مغطى نقدا بالكامل ، فاذا غطى بعضه نقدا فرضت الضريبة على ما لم يغط .
واذا زادت مدة العقد أو العملية أو مدة التجديد على سنة وجب أداء الضريبة ذاتها عن كل سنة اضافية أو كسورها .
وبالنسبة للاعتماد غير محدد القيمة تحسب الضريبة على أكبر رصيد مدين يصله الاعتماد خلال مدة نفاذه .
(2) عقود تحويل الأموال أو النزول عنها :
ثلاثة فى الألف بحد أدنى ستون مليما .
ولا تخضع لهذه الضريبة أوامر النقل فى المصارف والأوراق التى تصدر تنفيذا لها .
(3) السلف والقروض والاقرار بالدين :
واحد فى الألف عن كل مبلغ يزيد على مائة جنيه ولا يجاوز مائتى جنيه .
ثلاثة فى الألف عن كل مبلغ يزيد على مائتى جنيه ولا يجاوز عشرة آلاف جنيه .
أربعة فى الألف عن كل مبلغ يزيد على عشرة آلاف جنيه .
وتعفى من الضريبة الودائع الآجلة بكافة أنواعها فى المصارف وهيئة البريد .$m250$,'26582fe980a9afcd14410d00e2b5585a'),
(58,0,$m250$المادة 58$m250$,$m250$تستحق الضريبة النوعية على الأعمال والمحررات المصرفية على الوجه الآتى :
(1) الحساب المصرف :
ثلاثمائة مليم سنويا على كل حساب يفتح فى المصارف .
وتخفض الضريبة بالنسبة لحساب التوفير الى خمسين مليما سنويا .
(2) أذون التسوية :
خمسون مليما عن كل اذن تسوية فى المصارف .
(3) أوامر النقل المصرف :
مائة مليم عن كل أمر نقل مصرفى الذى بمقتضاه يصدر الأمر الى المصرف بتحويل مبلغ لحساب الغير الذى ليس له حساب بالمصرف خصما على حساب مصدر الأمر .
(4) كشوف ومستخرجات الحساب :
خمسون مليما على كل كشف أو مستخرج حساب مما تصدره المصارف الى عملائها الذين لهم حساب فى المصرف .
وتعفى من الضريبة اشعارات الاضافة والخصم التى ترسلها المصارف الى عملائها .
(5) حوافظ التحصيل :
ثلاثون مليما على حافظة تحصيل حصص أرباح الأسهم وفوائد السندات وذلك بغير اخلال بالضريبة المفروضة على الايصالات اذا اشتملت الحافظة على ايصال .
(6) خطابات الضمان وعقود الكفالة :
خمسمائة مليم على كل خطاب ضمان . وعقد الكفالة ، وضمان الأوراق التجارية أيا كان نوعه اذا أعطى فى محرر مستقل .$m250$,'fd2c25b5a0b7fe656f9cab5301539c02'),
(59,0,$m250$المادة 59$m250$,$m250$يتحمل الضريبة المفروضة طبقا للمادة السابقة الأشخاص الآتى ذكرهم :
(1) فتح الاعتماد : يتحمل الطرفان بالتساوى الضريبة .
(2) السلف والاقرار بالدين : يتحمل الضريبة المقرض أو الدائن اذا كان القرض بفائدة ، ويتحمل الضريبة المقترض أو المدين اذا كان القرض بدون فائدة .
(3) فتح الحساب ، وكشف مستخرج الحساب ، وحافظة التحصيل : يتحمل العميل الضريبة .
(4) اذن التسوية ، وأمر النقل المصرف : يتحمل مصدر الأمر الضريبة .
(5) خطاب الضمان ، وعقد الكفالة وضمان الأوراق التجارية : يتحمل المكفول أو من تسلم العقد الضريبة .$m250$,'1764dcf210d77d2a8f36dc72a5ee5b2d'),
(60,0,$m250$المادة 60$m250$,$m250$يعتبر اعلانا كل اعلام أو اخطار أو تبليغ يتم بأية وسيلة ، وتستحق عليه الضريبة على الوجه الآتى :
(أ) ستون مليما عن كل نسخة من الاعلانات على الورق العادى المعلنة أو الملصقة فى الطرقات العامة .
مائة وعشرون مليما اذا علق أو ألصق الاعلان المشار اليه فى غير الطرقات العامة .
(ب) مائتان وأربعون مليما عن كل نسخة من الاعلانات على الورق المعد بحيث يطول بقاؤه بأية وسيلة .
فاذا كان الاعلان على تقويم سنوى تكون ضريبته ثلاثين مليما عن كل نسخة .
(ج) ستمائة مليم سنويا عن كل نسخة من الاعلانات على غير الورق .
فاذا كان الاعلان يوزع كهدايا تكون ضريبته خمسين مليما عن كل نسخة .
وتعفى من الضريبة العينات الطبية .
(د) ستمائة مليم أسبوعيا عن الاعلانات التى تنشر فى برامج المحلات الخاضعة لضريبة الملاهى أو التى توزع معها .
وتؤدى الضريبة مقدما ، ولا ترد اذا لم يستمر الاعلان أسبوعا كاملا .
(هـ) جنيهان وأربعمائة مليم سنويا عن كل متر مربع أو كسوره من مساحة الاعلان المضىء اضاءة ثابتة .
(و) أربعة وعشرون جنيها سنويا عن كل متر مربع أو كسوره من مساحة الاعلان المضىء اضاءة غير ثابتة أو اضاءة متقطعة .
ويعتبر الاعلان مضيئا اذا أضيئت حروفه أو رسوماته أو علاماته أو اطاره كلها أو بعضها ، ويستوى أن يكون الاعلان مضيئا بذاته أو بانعكاس الضوء عليه أو بأية وسيلة أخرى .
ويتم حساب المساحة التى تحصل عليها الضريبة المقررة فى البندين هـ ، و على النحو التالى :
1 - اذا وجد اطار مضىء للاعلان حسبت المساحة وفقا لأبعاد الاطار بصرف النظر عن الكتابة داخله .
2 - اذا لم يكن الاعلان المضىء داخل اطار أو كان اطاره غير مضىء حسبت المساحة على أساس المستطيل أو المربع الذى تمر أضلاعه بالنقط القصوى لحروف الكتابة أو الرسوم المعلن عنها .
3 - اذا تعددت الاعلانات فى وقت واحد داخل اطار مضىء حسبت الضريبة على كل منها وفقا لأبعاده الخاصة على حده كاعلان مستقل فى غير اطار ما لم تكن الاعلانات المتعددة كل منها داخل اطار خاص فتحسب الضريبة على أساس أبعاد اطار كل منها .
وتؤدى الضريبة مقدما ، ولا ترد اذا لم يستمر الاعلان سنة كاملة .
(ز) مائة وثمانون مليما عن كل جنيه أو كسوره من أجر المعرض بالنسبة للاعلانات على لوحات دور السينما أو شاشة التليفزيون وما شابهها ، بما فى ذلك مقدمات الأفلام التى ستعرض مستقبلا فى دار السينما ولو كانت ملكا لهذه الدار .
(ح) مائة وعشرون مليما عن كل جنيه أو كسوره من أجر الاذاعة بالنسبة للاعلانات التى تذاع بالراديو .
(ط) جنيهان وأربعمائة مليم عن الاعلانات على الورق أو على أغلفة الكبريت أو ما يماثلها توزع باليد أو ترسل بالبريد أو تطبع على الاشارات البرقية .
(ى) مائة وثمانون مليما عن كل جنيه أو كسوره من أجر النشر بالنسبة للاعلانات التى تنشر فيما يطبع ويوزع فى مصر من الصحف والمجلات والتقاويم السنوية وكتب الدليل والكراسات والنشرات الدورية على اختلاف أنواعها .$m250$,'9d7650ecb91bc641e0c1b75a13b240d4'),
(61,0,$m250$المادة 61$m250$,$m250$على أصحاب دور الطبع والنشر ومديرى البيوت المشتغلة بالاعلانات وشركات النيون ومن يعمل بالاعلان لمصلحته أن يخطروا مصلحة الضرائب عن الاعلانات التى يتم طبعها أو صنعها .
ويكون الاخطار من نسختين ، ويوضح به نص الاعلان وشكله ومساحته بالمتر المربع ، وعدد النسخ أو الوحدات الموزعة ، والمكان الذى توضع به كل نسخة أو وحدة ، ومدة الاعلان .
ويقدم الاخطار الى مأمورية الضرائب المختصة قبل تعليق أو لصق أو عرض أو نشر الاعلان .$m250$,'12eb9ed342a796d26eeea3d5008a68ae'),
(62,0,$m250$المادة 62$m250$,$m250$تتعدد الضريبة بعدد الاعلانات داخل اللوحة أو اللافتة أو الورقة أو النشرة الواحدة .
وفى حالة حساب الضريبة على أساس أجر الاعلان تحسب الضريبة على أساس أجر المثل اذا كان الاعلان مجانا .$m250$,'7e11af557bed4591d21ce021f8493d92'),
(63,0,$m250$المادة 63$m250$,$m250$تتحمل الضريبة المستحقة على الاعلانات من يعمل الاعلان لمصلحته ويكون الطابعون والناشرون وكل من توسط فى نشر الاعلان مسئولين بالتضامن عن أداء الضريبة وذلك فى حالة اخلالهم بواجب الاخطار المنصوص عليه فى المادة 61$m250$,'9710468048af3d135d750f0bbc7eaf7f'),
(64,0,$m250$المادة 64$m250$,$m250$يعفى من الضريبة الاعلانات الآتية :
(أ) الاعلانات التى تصدر بقصد الاعلام بأوامر السلطة العامة : أو لتنبيه الجمهور الى تنفيذ القوانين واللوائح ، أو التوعية بصفة عامة ، بما فى ذلك الاعلانات الصادرة من ادارات السياحة والاستعلامات الحكومية .
(ب) اعلانات التحذير .
(ج) الاعلانات الخاصة بالبيوع الجبرية .
(د) الاعلانات الخاصة بالانتخابات .
(هـ) اعلان طالب الحصول على عمل .
(و) اعلانات الوفاة .
(ز) الاعلانات الخاصة بتنظيم العمل بالمنشآت .
(ح) الاعلانات غير المضيئة التى تبين اسم المحل أو نوع نشاطه سواء كانت داخل المنشأة أو خارجها ، وكذلك الاعلانات المضيئة داخل المنشأة لتلك الأغراض .$m250$,'aa29ea7ac284992903e10d09a533736d'),
(65,0,$m250$المادة 65$m250$,$m250$تلتزم الجهات التالية بتوريد الضريبة المستحقة الى مصلحة الضرائب فى المواعيد التى تحددها اللائحة التنفيذية ولو لم يكن أجر الاعلان قد تم تحصيله .
(أ) المنشأة المشتغلة بالاعلانات بالنسبة الى ما تتولى نشره منها .
(ب) دور الصحف بالنسبة الى ما ينشر فيها من اعلانات .
(ج) دور السينما بالنسبة الى ما يعرض فيها من اعلانات .
(د) هيئة الاذاعة والتليفزيون بالنسبة الى الاعلانات التى تذاع عن طريقها .$m250$,'e9d1f6c84778b813babcd1fe67c75d1b'),
(66,0,$m250$المادة 66$m250$,$m250$يحظر على الجهات المشار اليها فى المادة السابقة اجراء الاعلان أو النشر الا بعد أداء الضريبة المستحقة الى مأمورية الضرائب الختصة .
ويعتبر الموظف المختص بكل جهة من هذه الجهات مسئولا عن أداء الضرائب التى لم يتم توريدها الى مصلحة الضرائب .$m250$,'ddcb3bf4f3de543e175caedd4da847c5'),
(67,0,$m250$المادة 67$m250$,$m250$تستحق الضريبة بالنسبة الى خدمات النقل على الوجه الآتى :
أولا : نقل الأشخاص :
(1) تسعمائة مليم عى كل اشتراك بالدرجة الأولى صادر من هيئة السكة الحديد أو من أية هيئة أو منشأة أخرى تقوم بأعمال النقل بين المدن .
(2) أربعمائة وخمسون مليما على الاشتراك المشار اليه فى البند السابق اذا كان بالدرجة الثانية .
وتخفض الضريبة المنصوص عليها فى البندين السابقين الى النصف اذا كانت مدة الاشتراك لا تجاوز ثلاثة شهور .
(3) تسعون مليما على كل اشتراك للانتقال بوسائل النقل العامة داخل المدن ، أو بين المدينة الواحدة وضواحيها .
وتخفض الضريبة الى النصف اذا كانت مدة الاشتراك لا تجاوز ثلاثة شهور .
(4) تسعمائة مليم سنويا على كل اشتراك أو تصريح سفر مجانا .
(5) مائتا مليم سنويا على كل اشتراك أو تصريح سفر مخفض وتعفى من الضريبة :
(أ) التراخيص والاشتراكات التى تعطى لموظفى الهيئة القائمة بالنقل بسبب أداء وظائفهم ولدواعى عملهم ، ودون أن تتضمن امتيازا شخصيا لصاحبها .
(ب) التراخيص والاشتراكات التى تعطى بغير اسم الى الجهات الحكومية لاستعمالها فى أغراض مصلحية .
(ج) التراخيص والاشتراكات التى تصرف لتسهيلات القوات المسلحة لأعمال مصلحية .
(د) التراخيص والاشتراكات التى تصرف مجاملة من هيئة السكة الحديد وفقا لما جرى عليه العرف وتحدده لائحتها .
(هـ) التراخيص والاشتراكات التى تصرف مخفضة الأجرة للملاجىء والفرق الرياضية والطلبة والمكفوفين والمعوقين .
6 - أربعمائة وخمسون مليما على كل تذكرة فى عربات النوم بقطارات السكة الحديد .
7 - مائة وثمانون مليما على كل تذكرة فى الدرجة الأولى الممتازة .
8 - مائة وعشرون مليما على كل تذكرة فى الدرجة الثانية الممتازة .
9 - جنيه وثمانمائة مليم على كل تذكرة سفر على السفن بالدرجة الأولى .
10 - جنيه وثلاثمائة وخمسون مليما على كل تذكرة سفر على السفن بالدرجة الثانية .
11 - أربعمائة وخمسون مليما على كل تذكرة سفر على السفن بالدرجة الثالثة .
وتخفض الضريبة بالنسبة لتذاكر السفر على السفن لأداء الحج أو العمرة بالدرجتين الأولى والثانية الى مائتى مليم ومائة وخمسين مليما على التوالى .
وتعفى من الضريبة تذاكر السفر على السفن فى الأحوال الآتية :
(أ) تذاكر السفر للحج أو للعمرة بالدرجة الثالثة .
(ب) تذاكر العودة اذا دفعت قيمتها فى الجمهورية .
(ج) تذاكر السفر داخل الجمهورية .
(د) تذاكر السفر على ظهر الباخرة .
12 - جنيه وثمانمائة مليم على كل تذكرة سفر على الطائرات للخارج .
13 - أربعمائة وخمسون مليما على كل تذكرة سفر على الطائرات داخل الجمهورية وتخفض الضريبة الى النصف على تذاكر السفر على الطائرات لأداء الحج أو العمرة .
وتعفى من الضريبة على تذاكر السفر على الطائرات :
(أ) تذاكر العودة اذا دفعت قيمتها فى الجمهورية .
(ب) التذاكر التى صرفت فى الخارج لمسافرين مارين بالجمهورية واستعملت فيها .
ثانيا : نقل البضائع :
1 - نوعية : مائتان وسبعون مليما على كل ورقة منأوراق وثيقة (بوليصة) الشحن البحرى .
2 - نسبية : تسعة فى المائة بحد أقصى ثلاثمائة مليم من أجر النقل على وثائق ( بوالص ) النقل الخاصة بالبضائع والمنقولات أيا كان نوعها سواء كان النقل بريا أو جويا أو بطريق الملاحة البحرية الداخلية .
3 - تسرى الضريبة المنصوص عليها فى البند السابق على تذاكر الأمتعة والمنقولات الخاصة بالبضائع التى تنقل بوسائل النقل المشار اليها فى البند المذكور .
وتعفى من الضريبة الوثائق والتذاكر المشار اليها اذا لم يجاوز أجر النقل جنيها .$m250$,'356519b77a19d164093b75d8250a4418'),
(68,0,$m250$المادة 68$m250$,$m250$تتعدد الضريبة بتعدد الأشخاص فى كل تذكرة أو ترخيص أو اشتراك .$m250$,'b8a00b34f865a8a493cda39266202363'),
(69,0,$m250$المادة 69$m250$,$m250$يتحمل الضريبة على خدمات النقل صاحب التذكرة أو الاشتراك أو الترخيص أو مرسل البضاعة .$m250$,'2fdec80ec900a7e500eda3fdb8d8a58c'),
(70,0,$m250$المادة 70$m250$,$m250$يلتزم متعدو النقل - من غير الجهات الحكومية - بسداد الضريبة المستحقة الى مصلحة الضرائب خلال العشرة أيام الأولى من كل شهر مصحوبا باخطار تبين به عدد الوثائق أو الاستمارات أو التذاكر التى صرفت خلال الشهر السابق ، مع عدم الاخلال بحقهم فى الرجوع على من تم النقل لصالحه بقيمة تلك الضريبة .$m250$,'d23dc35db30e5e55eef4a63957494109'),
(71,0,$m250$المادة 71$m250$,$m250$تستحق الضريبة على خدمات البريد على النحو التالى :
(أ) نوعية على ما يأتى :
1 - خمسة عشر مليما عن كل طرد بريد داخلى .
2 - عشرون مليما عن كل طرد بريد خارجى .
3 - خمسة وأربعون مليما عن كل طرد محول عليه .
4 - تسعون مليما عن كل طرد مؤمن عليه .
5 - خمسة وعشرون مليما عن كل حوالة .
6 - خمسة وأربعون مليما عن كل ورقة تحصيل بواسطة هيئة البريد .
7 - تسعون مليما عن كل صر نقود يرسل بواسطة هيئة البريد .
8 - تسعون مليما عن كل خطاب مؤمن عليه .
9 - خمسة وعشرون مليما عن كل خطاب يسلم فى شباك البريد بالمدن .
10 - مائة قرش سنويا عن كل تأجير صندوق بريد خاص .
وتحصل هذه الضريبة عن الصناديق المؤجرة وقت العمل بهذا القانون عن المدة الباقية من السنة .
11 - مائة وخمسون مليما سنويا عن الحساب الجارى .
(ب) ضريبة نسبية مقدارها أربعة ونصف فى الألف عن كل مبلغ يحصل بواسطة هيئة البريد وبحد أقصى أربعمائة وخمسون مليما .$m250$,'bb4bbb00fe8f3e6a0395d4e86cc7defb'),
(72,0,$m250$المادة 72$m250$,$m250$اذا شمل المحرر البريدى عدة أحكام مما تخضع للضريبة المنصوص عليها فى هذا القانون فلا يحصل عنه سوى الضريبة المنصوص عليها فى المادة السابقة .$m250$,'db89ad4fb7aa35044bb6a8e953b15622'),
(73,0,$m250$المادة 73$m250$,$m250$يتحمل المتعامل مع الهيئة الضريبة المستحقة على الخدمة البريدية .$m250$,'0378c97d5d17a54f1b9f03f3e1422f25'),
(74,0,$m250$المادة 74$m250$,$m250$تستحق ضريبة نسبية مقدارها ثلاثون فى المائة على المبالغ المعدة للأداء لجميع الراهنين فى مراهنات سباق الخيل وصيد الحمام وغيرها من أنواع المراهنات .$m250$,'8465f6ab0b585dc8418f96698787f11a'),
(75,0,$m250$المادة 75$m250$,$m250$تستحق ضريبة نسبية على اليانصيب على النحو التالى :
(أ) ثلاثون فى المائة من المبالغ المخصصة للرابحين نقدا أو عينا ، وتخفض الضريبة الى النصف اذا وقع الربح من نصيب الجهة مصدرة اليانصيب .
(ب) خمسة عشر فى المائة من الأنصبة والمزايا التى يحصل عليها حاملوا السندات والمؤمن لهم والمدخرون عن طريق السحب بالقرعة الذى تجريه الجهات العامة والخاصة التى أصدرت السندات أو الأوراق .
وتعفى تلك الأنصبة والمزايا من ضريبة الدمغة اذا خضعت للضريبة على ايراد القيم المنقولة وسددت عنها تلك الضريبة .$m250$,'bae507c16dc8403bb4d0fa89804ff4da'),
(76,0,$m250$المادة 76$m250$,$m250$يتحمل الضريبة المنصوص عليها فى المادتين السابقتين الرابح .$m250$,'93665b98ddf5fc22f7a3608574b444eb'),
(77,0,$m250$المادة 77$m250$,$m250$يعفى منالضريبة الربح العينى اذا لم تجاوز قيمته عشرةجنيهات .$m250$,'8aee40e5adc6399ad8f3e0d48b53006c'),
(78,0,$m250$المادة 78$m250$,$m250$يجوز تقسيط الضريبة المستحقة على الربح العينى منقولا كان أو ثابتا ، وذلك طبقا للشروط التى تحددها مصلحة الضرائب .$m250$,'7cbe3f4d3c29690218ae061cda9f4462'),
(79,0,$m250$المادة 79$m250$,$m250$تستحق ضريبة نسبية على ما تصرفه الجهات الحكومية وشركات القطاع العام من المرتبات والأجور والمكافآت وما فى حكمها والاعانات على الوجه الآتى :
الخمسون جنيها الأولى ...... ...... ...... ...... معفاة
أزيد من خمسين - مائتين وخمسين جنيه ...... ستة فى الألف
أزيد من مائتين وخمسين - خمسمائة جنيه ...... ستة ونصف فى الألف
أزيد من خمسمائة - ألف جنيه ...... ...... سبعة فى الألف
أزيد من ألف - خمسة آلاف جنيه ...... ...... سبعة ونصف فى الألف
أزيد من خمسة آلاف - عشرة آلاف جنيه ...... ثمانية فى الألف
وكل ما يزيد على عشرة آلاف جنيه تستحق عنه الضريبة بواقع ثلاثة فى الألف من الزيادة .$m250$,'57232dd5c800113a1b10dacd45ee1efa'),
(80,0,$m250$المادة 80$m250$,$m250$فيما عدا المرتبات والأجور وما فى حكمها والاعانات تستحق على كل مبلغ تصرفه الجهات الحكومية من الأموال المملوكة لها ، وسواء تم الصرف مباشرة أو بطريق الانابة علاوة على الضريبة المبينة فى المادة السابقة ضريبة اضافية مقدارها ثلاثة أمثال الضريبة المشار اليها .
ويقصد بالصرف عن طريق الانابة أن تعهد الجهة الحكومية الى أى شخص بمبلغ مملوك لها ليتولى الصرف منه نيابة عنها .$m250$,'635398fb7569b7f006cf755f7221a485'),
(81,0,$m250$المادة 81$m250$,$m250$يتحمل الضريبة الشخص أو الجهة التى يتم الصرف لها ، وفى جميع الأحوال يجب ألا يقل صافى المبلغ المنصرف بعد خصم الضريبة المنصوص عليها فى المادتين السابقتين عن صافى أى مبلغ يقل عنه .$m250$,'9e9839c4f9f0a94bca2cd622da980f60'),
(82,0,$m250$المادة 82$m250$,$m250$تعفى من الضريبة المنصوص عليها فى المادتين 79 ، 80 من هذا القانون المبالغ التى تصرف فى الأحوال الآتية :
(أ) اذا كان الصرف ردا لمبالغ مسبق صرفها .
(ب) الصرف لهيئة دولية .
(ج) الصرف احكومة أجنبية بشرط المعاملة بالمثل .
(د) الصرف على أساس أسعار احتكارات دولية .
(هـ) ما يصرف ثمنا لشراء أوراق مالية .
(و) ما يصرف نظير مشتريات مسعره جبريا ، أو خدمات محدد مقابل أدائها بمعرفة احدى الجهات الحكومية .
(ز) ما يصرف فى الخارج .$m250$,'bd23adac890a4c3cbc56954e45960f78'),
(83,0,$m250$المادة 83$m250$,$m250$تستحق ضريبة سنوية على السندات أيا كانت جهة اصدارها .
وجميع الأسهم والحصص والأنصبة الصادرة من الشركات المصرية سواء كانت مساهمة . أو توصية بالأسهم : أو ذات مسئولية محدودة وسواء مثلت تلك الأسهم والحصص والأنصبة والسندات فى صكوك أو لم تمثل : وسواء سلمت الصكوك لأصحابها أم لم تسلم وذلك على النحو التالى :
(أ) نسبية : أربعة فى الألف من متوسط السعر خلال الستة الأشهر السابقة على تاريخ استحقاق الضريبة وذلك بالنسبة للأوراق المقيدة والمتداولة فى البورصة .
(ب) نسبية : ستة فى الألف من القيمة الاسمية للأوراق غير المقيدة فى البورصة أو المقيدة بها التى ترى مصلحة الضرائب أن العمليات التى تمت بشأنها فى البورصة من القلة بحيث لا يمثل متوسط أسعارها القيمة الحقيقية لها .
(ج) نسبية : ستة فى الألف من قيمة رأس مال الشركات المساهمة وذات المسئولية المحدودة فى الممثل فى أسهم أو حصص أو أنصبة .
(د) نوعية : ثلاثمائة مليم بالنسبة لحصص التأسيس غير المقيدة فى البورصة أو المقيدة بها التى ترى مصلحة الضرائب أن العمليات التى تمت بشأنها من القلة بحيث لا يمثل متوسط أسعارها القيمة الحقيقية لها .
وتخفض الضريبة الى النصف خلال السنتين الأوليين من تاريخ تأسيس الشركة .$m250$,'21c8cb6eaf066e46824f0ba674f54de6'),
(84,0,$m250$المادة 84$m250$,$m250$تعد فى حكم الشركات المصرية المنصوص عليها فى المادة السابقة وتخضع للضريبة المقررة فيها :
(أ) كل شركة أجنبية يكون مقرها الرئيسى فى جمهورية مصر العربية ولو شمل نشاطها بلاد أخرى .
(ب) كل شركة أجنبية يكون غرضها الوحيد أو غرضها الرئيسى الاستثمار فى جمهورية مصر العربية ولو كان مقرها فى الخارج .
(ج) فروع الشركات والبنوك الأجنبية المخصص لنشاطها فى جمهورية مصر العربية رأس مال محدد .$m250$,'1ad5bd7a25f7587f46a01cc2e2f8926b'),
(85,0,$m250$المادة 85$m250$,$m250$تسرى الضريبة من تاريخ مزاولة الشركة عملها ، أو من تاريخ صدور القرار المرخص فى تأسيسها ، أو من تاريخ نشرالمحرر الذىأسست بمقتضاء أى هذه التواريخ أسبق .$m250$,'84548e347dcef4ec37359b4b9489fdf0'),
(86,0,$m250$المادة 86$m250$,$m250$تستحق الضريبة مقدما فى أول يناير من كل سنة ، ويقع عبؤها على صاحب الورقة المالية أو الحصة أو النصيب .
وعلى الشركات والهيئات التى أصدرت الورقة أو الحصة أو النصيب أن تؤدى الضريبة الى مصلحة الضرائب خلال الخمسة عشر يوما الأولى من يناير من كل سنة .
وتعفى من الضريبة الشركات تحت التصفية .$m250$,'6500afb727d0159a0fc08d45c1135e45'),
(87,0,$m250$المادة 87$m250$,$m250$تستحق الضريبة بالنسبة للشركات التىتؤسس أوتزيد رأسمالها بعد أول يناير بنسبة المدة الباقية من السنة مع عدم حساب كسور الشهر .
وتؤدى الضريبة الى مصلحة الضرائب خلال الخمسة عشر يوما التالية لتأسيس الشركة أو الاكتتاب فى زيادة رأس المال .$m250$,'62e6c56a48e9fd0878fda17405b5cd27'),
(88,0,$m250$المادة 88$m250$,$m250$تخضع عمليات بيع وشراء الأوراق المالية للضريبة على النحو التالى :
(أ) نسبية مقدارها واحد فى الألف بحد أدنى ثلاثمائة مليم وحد أقصى اثنى عشر جنيها على جميع عمليات شراء أو بيع الأوراق المالية مصرية كانت أو أجنبية .
(ب) نسبية مقدارها ستة فى الألف على كل عملية بيع أو شراء أوراق مالية أجنبية مما لا تخضع للضريبة النسبية السنوية : وذلك علاوة على الضريبة النسبية المنصوص عليها فى البند السابق :
ويتحمل الضريبة المنصوص عليها فى الفقرتين السابقتين كل منالبائع والمشترى ، وتحسب على قيمة المبالغ الواجبة الأداء أو المستحقة التحصيل .$m250$,'6693b26a9ceac64a8a540a232261037e'),
(89,0,$m250$المادة 89$m250$,$m250$تستحق الضريبة على النحو التالى :
أولا - التصاريح :
نوعية مقدارها مائة وخمسون مليما على كل تصريح يصدر من أية سلطة ادارية .
ثانيا - الرخص :
نوعية خمسمائة مليم عن كل رخصة تصدر من أية سلطة ادارية وذلك عدا الرخص الآتى بيانها فتستحق عليها الضريبة كما يلى :
(أ) عشرة جنيهات سنويا على ترخيص استغلال محجر أو منجم .
(ب) خمسة جنيهات سنويا على رخصة محال الملاهى ودور التسلية بما فى ذلك دور السينما والمسارح .
(ج) خمسة جنيهات سنويا على كل ترخيص لاستغلال مصنع طوب .
(د) خمسة جنيهات على رخصة البناء .
(هـ) جنيهان سنويا على رخصة تسيير سيارة نقل حمولة خمسة أطنانفأقل .
(و) جنيهان ونصف سنويا على رخصة تسيير سيارة نقل تزيد حمولتها على خمسة أطنان ولا تجاوز خمسة عشر طنا .
(ز) ثلاثة جنيهات سنويا على رخصة تسيير سيارة نقل تزيد حمولتها على خمسة عشر طنا .
(ح) جنيهان سنويا على كل رخصة محل عام .
(ط) ثلاثة جنيهات سنويا على ترخيص محل جزارة أو محل صناعى .
(ى) جنيه سنويا على رخصة تسيير سيارة ركوب أربعة سلندرات فأقل .
(ك) جنيهان سنويا علىرخصة تسيير سيارة ركوب أكثرمنأربعة سلندرات .
(ل) جنيه واحد عن كل رخصة لاستيراد أسلحة أو ذخائر أو نقلها .$m250$,'55382bf0d6394205eed6e3adc1c194d9'),
(90,0,$m250$المادة 90$m250$,$m250$تستحق الضريبة فى حالة التنازل عن الرخصة أو تجديدها أو امتدادها أو اجراء أى تعديل فيها .$m250$,'928ec939b77ba4757b05492705efaafc'),
(91,0,$m250$المادة 91$m250$,$m250$يتحمل الضريبة على التصاريح والرخص من صدر لصالحه التصريح أو الرخصة .$m250$,'ae32e7502057542106f5fd44e855aee3'),
(92,0,$m250$المادة 92$m250$,$m250$يعفى من الضريبة ترخيص نقل القطن المحلوج .$m250$,'d81caf246c2c389785c22d31251fe720'),
(93,0,$m250$المادة 93$m250$,$m250$تستحق ضريبة نوعية على كل شركة عند تأسيسها أو تكوينها على الوجه الآتى :
(أ) ثلاثمائة جنيه على الشركة المساهمة .
(ب) مائة وخمسون جنيها على شركة التوصية بالأسهم ، والشركة ذات المسئولية المحدودة .
(ج) خمسة عشر جنيه على شركة التوصية البسيطة أو شركة التضامن التى يزيد رأس مالها على خمسة آلاف جنيه .
وتتحمل الشركة بهذه الضريبة .$m250$,'8a81c6c44a5073d8fce8ba8e495ebac1'),
(94,0,$m250$المادة 94$m250$,$m250$يستحق على زيادة رأس مال الشركات ضريبة نوعية كالآتى :
(أ) عشرون جنيها بالنسبة للشركة المساهمة .
(ب) عشرة جنيهات بالنسبة لشركة التوصية بالأسهم والشركة ذات المسئولية المحدودة .
وتتحمل الشركة بهذه الضريبة .$m250$,'6f93cc2d50b7ef8b0f7f1bffebef5490'),
(95,0,$m250$المادة 95$m250$,$m250$تستحق ضريبة نوعية على الوجه الآتى :
(أ) مائة وخمسون جنيها على قيد كل وكيل أو ممثل تجارى لشركة أجنبية تعمل فى الجمهورية ، وعند تجديد هذا القيد .
(ب) تسعون جنيها عن القيد فى سجل الوكلاء التجاريين ، وعند تجديد هذا القيد .
(ج) ثلاثون جنيها عن تعديل بيانات القيد فى سجل الوكلاء التجاريين .
(د) خمسة جنيهات عن كل قيد فى السجل التجارى : وعند تجديد هذا القيد .
(هـ) ثلاثمائة مليم عن القيد أو الاشتراك أو الانضمام لأول مرة الى النقابات المهنية والغرف التجارية والغرف الصناعية ، وكذلك الى النوادى التى يجاوز الاشتراك فيها ثلاث جنيهات .
ويحصل نصف هذه الضريبة عن كل سنة من السنوات التالية للقيد أو الاشتراك أو الانضمام .
(و) خمسمائة مليم عن قيد كل تلميذ مستجد بالمدارس الخاصة أو المعاهد الخاصة وتسرى الضريبة على القيد فى كل مرحلة من مراحل التعليم المختلفة .
(ز) خمسون مليما عن كل ورقة من أوراق السجلات المنصوص عليها فى اللائحة التنفيذية لقانون الأسلحة والذخائر .
(ح) خمسة عشر مليما شهريا عن صرف المقررات التموينية التى توزع بالبطاقات .
ويتحمل عبء الضريبة :
1 - طالب القيد فى السجلات أو تعديله أو تجديده .
2 - صاحب بطاقة التموين ( المستهلك ) .
3 - صاحب سجل الأسلحة والذخائر .$m250$,'44c10724909cb484aaa65a1e098e416a'),
(96,0,$m250$المادة 96$m250$,$m250$تستحق ضريبة نوعية على النحو التالى :
(أ) خمسمائة مليم سنويا على توريد كل من المياه أو الكهرباء أو الغاز ولو قلت مدة التوريد الفعلى عن سنة كاملة .
(ب) خمسة مليمات على كل كيلووات ساعة من الكهرباء المستعملة للاضاءة فى أى مكان ، أو للأغراض السكنية أو التجارية بما فى ذلك ادارة المصاعد .
(ج) مليم على كل عشرة كيلووات ساعة من الكهرباء المستعملة فى الأغراض الصناعية .
(د) ستة مليمات عن كل متر مكعب من استهلاك الغاز فى غير الأغراض الصناعية .
(هـ) خمسة عشر مليما عن كيلوجرام من استهلاك البيوتين ( البوتاجاز ) أو ما يماثله من المستحضرات فى غير الأغراض الصناعية .
(ز) خمسمائة مليم للطن من استهلاك الغاز والبوتاجاز فى الأغراض الصناعية .$m250$,'428f19b976a55ed8ae72612eb07e2ee3'),
(97,0,$m250$المادة 97$m250$,$m250$يتحمل الضريبة :
(أ) المورد بالنسبة للتوريد .
(ب) المستهلك بالنسبة للاستهلاك .$m250$,'1874ac2369fcca15dca72127e9181a62'),
(98,0,$m250$المادة 98$m250$,$m250$يعفى من الضريبة :
(أ) دور العبادة .
(ب) الملاجىء والمستشفيات والمستوصفات التى لا تبغى الكسب أو التابعة لهيئات لا ترمى الى الكسب .
(ج) الاستهلاك الذاتى من مولدات كهربائية خاصة بالمستهلك : واذا امتد الاستهلاك الى الغير استحقت الضريبة .
(د) المنشآت المقامة طبقا للقانون 32 لسنة 64 بشأن الجمعيات والمؤسسات الخاصة .$m250$,'e99fb14d15aa0814530c30a74654cd45'),
(99,0,$m250$المادة 99$m250$,$m250$تستحق ضريبة نوعية سنوية مقدارها جنيه واحد على كل اشتراك لاستعمال تليفون ، وخمسون جنيها عن كل اشتراك لاستعمال تلكس .
ويتحمل عبء الضريبة المشترك .$m250$,'82d4993b40db9de3389dc498479c3619'),
(100,0,$m250$المادة 100$m250$,$m250$تتعدد الضريبة بتعدد الخطوط الأصلية فى كل اشتراك .$m250$,'1bb4831b05907d147bd97c88364e0be0'),
(101,0,$m250$المادة 101$m250$,$m250$تستحق ضريبة نوعية مقدارها ثمانون مليما على شهادات وكشوف وزن البضائع التى يحررها الأشخاص المرخص لهم بالقيام بعمليات الوزن للجمهور .
ويتحمل الضريبة طالب الوزن .$m250$,'9107a4c3e6e91a12d2aa242d938bcd54'),
(102,0,$m250$المادة 102$m250$,$m250$تستحق ضريبة نوعية مقدارها خمسمائة مليم على كل اقرار ذمة أو ثروة مالية يقدم تنفيذا لأحكام القانون رقم 62 لسنة 1975 فى شأن الكسب غير المشروع ، والقانون رقم 46 لسنة 1978 فى شأن تحقيق العدالة الضريبية .
ويتحمل الضريبة مقدم الاقرار .$m250$,'339f5e0ff7602eee1644a40676134444'),
(103,0,$m250$المادة 103$m250$,$m250$يستحق على قرار منح الجنسية المصرية ضريبة نوعية مقدارها مائتا جنيه .
ويعفى من هذه الضريبة من ينتمى بجنسه لغالبية السكان فى بلد لغته العربية أو دينه الاسلام ولا تسمح حالته المالية بأداء هذه الضريبة ، وذلك متى قدم طلبا لاعفائه منها الى رئيس مصلحة الضرائب .$m250$,'9d0bc5ee128b4b52d9ad5fdc174ef43b'),
(104,0,$m250$المادة 104$m250$,$m250$تستحق ضريبة نوعية سنوية مقدارها مائة وخمسون قرشا على كل ميزان يتحرك بوضع قطعة عملة فيه .
ولا يجوز تركيب ميزان الا بعد أن توضع عليه لوحة تدل على اداء الضريبة .$m250$,'1e13adf87b4cacb785d617a51b7009d3'),
(105,0,$m250$المادة 105$m250$,$m250$تستحق ضريبة نوعية سنوية مقدارها ستة جنيهات على كل جهاز يعتمد فى ادارته على المهارة أو الصدفة ويكون الغرض منه امكان الحصول على ربح من أى نوع فى مقابل مبلغ ما .
ولا يجوز تركيب أى جهاز الا بعد أن توضع عليه لوحة تدل على اداء الضريبة .$m250$,'0f7c29368d2dd9579d5a553651dae837'),
(106,0,$m250$المادة 106$m250$,$m250$تستحق ضريبة نوعية سنوية مقدارها جنيه واحد عن كل آلة تسجيل نقد .
وتحصل الضريبة عن الآلات الموجودة وقت العمل بهذا القانون .
ولا يجوز استعمال أية آلة الا بعد أن توضع عليها لوحة تدل على أداء الضريبة .$m250$,'c1b3b1a27d5ba42ed79c1c7c38303826');

INSERT INTO m250_ver VALUES
(0,0,1,$m250$قانون رقم 111 لسنة 1980 بإصدار قانون ضريبة الدمغة
باسم الشعب
رئيس الجمهورية
قرر مجلس الشعب القانون الآتى نصه ، وقد أصدرناه :$m250$,'119718bf0358c231f4d5a90ed804dc82',DATE '1980-06-01',NULL,'active',NULL,NULL,$m250$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 مكرر (أ) فى 31 مايو 1980 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m250$),
(1,-1,1,$m250$يعمل بأحكام القانون المرافق بشأن ضريبة الدمغة .$m250$,'4de1e5f269b8a9bf2fbec45e8647a1d4',DATE '1980-06-01',NULL,'active',NULL,NULL,$m250$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 مكرر (أ) فى 31 مايو 1980 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m250$),
(2,-1,1,$m250$يلغى القانون رقم 224 لسنة 1951 بتقرير رسم دمغة والقوانين المعدلة له .$m250$,'d61b391069e0d778d3e56c87623a5d15',DATE '1980-06-01',NULL,'active',NULL,NULL,$m250$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 مكرر (أ) فى 31 مايو 1980 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m250$),
(3,-1,1,$m250$يصدر وزير المالية اللوائح والقرارات اللازمة لتنفيذ أحكام هذا القانون ، وإلى أن تصدر هذه اللوائح والقرارات يستمر العمل باللوائح والقرارات المعمول بها فيما لا يتعارض مع أحكام هذا القانون .$m250$,'9827bc8f68ae0e4057a21561e643ccf5',DATE '1980-06-01',NULL,'active',NULL,NULL,$m250$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 مكرر (أ) فى 31 مايو 1980 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m250$),
(4,-1,1,$m250$ينشر هذا القانون فى الجريدة الرسمية ، ويعمل به من اليوم التالى لتاريخ نشره .$m250$,'ae1ca224d7e2797691b06d55d9fd8f82',DATE '1980-06-01',NULL,'active',NULL,NULL,$m250$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 مكرر (أ) فى 31 مايو 1980 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m250$),
(1,0,1,$m250$تفرض ضريبة دمغة على المحررات والمطبوعات والمعاملات والأشياء والوقائع وغيرها من الأوعية المنصوص عليها فى هذا القانون .$m250$,'d1db899c3d69793d39e93f8d8ab27370',DATE '1980-06-01',NULL,'active',NULL,NULL,$m250$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 مكرر (أ) فى 31 مايو 1980 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m250$),
(2,0,1,$m250$ضريبة الدمغة نوعان :
(أ) ضريبة دمغة نوعية .
(ب) ضريبة دمغة نسبية .$m250$,'3afd2f9a02663e25b84f38dc71bc6178',DATE '1980-06-01',NULL,'active',NULL,NULL,$m250$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 مكرر (أ) فى 31 مايو 1980 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m250$),
(3,0,1,$m250$تستحق الضريبة على المحررات من تاريخ تحريرها ودون نظر الى صحتها . على أنه بالنسبة الى الحالتين الآتيتين يكون استحقاق الضريبة على المحررات عند استعمالها بعد العمل بأحكام هذا القانون :
(أ) اذا كانت محررة قبل 15/5/1939 تاريخ العمل بالقانون رقم 44 لسنة 1939 بتقرير رسم دمغة .
(ب) اذا كانت محررة فى الخارج واستعملت فى الجمهورية .
ويقصد بالاستعمال استخدام المحرر ذاته مباشرة فى أى عمل من شأنه أو يقصد به انتاج أثر من الآثار القانونية .
ويتحمل المستعمل الضريبة .
ولا ترد الضريبة مهما تكن الأسباب التى تجعل المحررات عديمة الأثر .$m250$,'0f8ce7b38ab137ab3abda9fae9d6b063',DATE '1980-06-01',NULL,'active',NULL,NULL,$m250$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 مكرر (أ) فى 31 مايو 1980 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m250$),
(4,0,1,$m250$تستحق الضريبة على غير المحررات من الوقائع والمعاملات من تاريخ تحققها ، وعلى الأشياء من تاريخ اعدادها الاعداد الذى تقتضيه طبيعتها والغرض منها .$m250$,'4999acad77603ab219f11b19b4d0fa30',DATE '1980-06-01',NULL,'active',NULL,NULL,$m250$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 مكرر (أ) فى 31 مايو 1980 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m250$),
(5,0,1,$m250$لا يجوز الاتفاق على ما يخالف الأحكام الواردة فى هذا القانون بالنسبة الى من يتحمل بعبء الضريبة .$m250$,'70a90e11101a7b367d3ab07bd3724e7f',DATE '1980-06-01',NULL,'active',NULL,NULL,$m250$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 مكرر (أ) فى 31 مايو 1980 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m250$),
(6,0,1,$m250$على أصحاب الشأن أن يضمنوا المحرر قيمة التعامل فى الأحوال التى يتوقف تحديد الضريبة فيها على هذه القيمة ، فاذا لم يتضمن المحرر قيمة التعامل ، أو رأت مصلحة الضرائب أن القيمة المذكورة فيه أو فى الاخطار الذى تؤدى بموجبه الضريبة تقل بمقدار يزيد على عشر القيمة الحقيقية فللمصلحة أن تقدر هذه القيمة وفقا لما يتكشف لها من أدلة وقرائن .
وعلى المصلحة اخطار الممول بالتقدير بكتاب موصى عليه مصحوب بعلم الوصول فاذا لم يتظلم الممول من التقدير خلال ثلاثين يوما من تاريخ تسلمه للاخطار يكون الربط نهائيا وتصبح الضريبة واجبة للأداء وفقا لتقدير المصلحة .
وللممول فى حالة عدم موافقته على هذا التقدير أن يتظلم منه بكتاب موصى عليه مصحوب بعلم الوصول الى المأمورية المختصة لاحالته الى لجنة الطعن المنصوص عليها فى المادة 50 من القانون رقم 14 لسنة 1939 وذلك خلال ثلاثين يوما من تاريخ تسلمه للاخطار بالتقدير .
وعلى الممول سداد الضريبة وفقا لقرار اللجنة الصادر فى هذا الشأن بمجرد تسلمه للتنبيه بالسداد من مأمورية الضرائب المختصة .
وللممول أن يطعن فى قرار اللجنة بدعوى أمام المحكمة الابتدائية التى يقع فى دائرتها وذلك خلال ثلاثين يوما من تاريخ تسلمه للقرار .
ولا يوقف الطعن أمام المحكمة وجوب أداء الضريبة .
