ويتحمل الضريبة طالب الوزن .$m250$,'9107a4c3e6e91a12d2aa242d938bcd54',DATE '1980-06-01',NULL,'active',NULL,NULL,$m250$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 مكرر (أ) فى 31 مايو 1980 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m250$),
(102,0,1,$m250$تستحق ضريبة نوعية مقدارها خمسمائة مليم على كل اقرار ذمة أو ثروة مالية يقدم تنفيذا لأحكام القانون رقم 62 لسنة 1975 فى شأن الكسب غير المشروع ، والقانون رقم 46 لسنة 1978 فى شأن تحقيق العدالة الضريبية .
ويتحمل الضريبة مقدم الاقرار .$m250$,'339f5e0ff7602eee1644a40676134444',DATE '1980-06-01',NULL,'active',NULL,NULL,$m250$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 مكرر (أ) فى 31 مايو 1980 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m250$),
(103,0,1,$m250$يستحق على قرار منح الجنسية المصرية ضريبة نوعية مقدارها مائتا جنيه .
ويعفى من هذه الضريبة من ينتمى بجنسه لغالبية السكان فى بلد لغته العربية أو دينه الاسلام ولا تسمح حالته المالية بأداء هذه الضريبة ، وذلك متى قدم طلبا لاعفائه منها الى رئيس مصلحة الضرائب .$m250$,'9d0bc5ee128b4b52d9ad5fdc174ef43b',DATE '1980-06-01',NULL,'active',NULL,NULL,$m250$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 مكرر (أ) فى 31 مايو 1980 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m250$),
(104,0,1,$m250$تستحق ضريبة نوعية سنوية مقدارها مائة وخمسون قرشا على كل ميزان يتحرك بوضع قطعة عملة فيه .
ولا يجوز تركيب ميزان الا بعد أن توضع عليه لوحة تدل على اداء الضريبة .$m250$,'1e13adf87b4cacb785d617a51b7009d3',DATE '1980-06-01',NULL,'active',NULL,NULL,$m250$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 مكرر (أ) فى 31 مايو 1980 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m250$),
(105,0,1,$m250$تستحق ضريبة نوعية سنوية مقدارها ستة جنيهات على كل جهاز يعتمد فى ادارته على المهارة أو الصدفة ويكون الغرض منه امكان الحصول على ربح من أى نوع فى مقابل مبلغ ما .
ولا يجوز تركيب أى جهاز الا بعد أن توضع عليه لوحة تدل على اداء الضريبة .$m250$,'0f7c29368d2dd9579d5a553651dae837',DATE '1980-06-01',NULL,'active',NULL,NULL,$m250$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 مكرر (أ) فى 31 مايو 1980 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m250$),
(106,0,1,$m250$تستحق ضريبة نوعية سنوية مقدارها جنيه واحد عن كل آلة تسجيل نقد .
وتحصل الضريبة عن الآلات الموجودة وقت العمل بهذا القانون .
ولا يجوز استعمال أية آلة الا بعد أن توضع عليها لوحة تدل على أداء الضريبة .$m250$,'c1b3b1a27d5ba42ed79c1c7c38303826',DATE '1980-06-01',NULL,'active',NULL,NULL,$m250$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 22 مكرر (أ) فى 31 مايو 1980 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m250$);

DO $m250$
DECLARE
  v_law uuid;
  v_title text;
  v_new_law boolean := false;
  v_ins_art int;
  v_ins_ver int;
  v_cnt int;
  v_vcnt int;
BEGIN
  IF (SELECT count(*) FROM m250_art WHERE md5(body) <> body_md5) <> 0 OR (SELECT count(*) FROM m250_ver WHERE md5(body) <> body_md5) <> 0 THEN
    RAISE EXCEPTION '[250] تلف فى نص أحد الصفوف داخل الملف';
  END IF;
  IF (SELECT count(*) FROM m250_art) <> 111 OR (SELECT sum(char_length(body)) FROM m250_art) <> 39738 OR (SELECT count(*) FROM m250_ver) <> 111 THEN
    RAISE EXCEPTION '[250] عدد الصفوف أو النسخ أو طول النص داخل الملف غير مطابق';
  END IF;

  SELECT id, title INTO v_law, v_title FROM laws WHERE country_code='EG' AND law_no=111 AND law_year=1980 AND kind='law';
  IF v_law IS NOT NULL AND v_title NOT LIKE '%الدمغة%' THEN
    RAISE EXCEPTION '[250] يوجد مستند آخر برقم 111 لسنة 1980 (%): لا يُدمج هذا النص فيه', v_title;
  END IF;
  IF v_law IS NULL THEN
    INSERT INTO laws (law_no, law_year, title, short_title, category, status, official_url, enacted_at, last_amended_at, country_code, kind, governance_scope)
    VALUES (111, 1980, $t250$القانون رقم 111 لسنة 1980 بإصدار قانون ضريبة الدمغة (النص الأصلى كما نشر بالجريدة الرسمية)$t250$, $t250$قانون ضريبة الدمغة 111/1980$t250$, 'other', 'in_force', NULL, DATE '1980-05-26', NULL, 'EG', 'law', false)
    RETURNING id INTO v_law;
    v_new_law := true;
  END IF;

  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, body)
  SELECT v_law, article_no, suffix, loc, body FROM m250_art
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING;
  GET DIAGNOSTICS v_ins_art = ROW_COUNT;

  INSERT INTO article_versions (article_id, version_no, body, effective_from, effective_to, status, amended_by_law_no, amended_by_law_year, change_note)
  SELECT a.id, m.version_no, m.body, m.eff, m.eff_to, m.status, m.am_no, m.am_yr, m.note
    FROM articles a JOIN m250_ver m ON m.article_no = a.article_no AND m.suffix = a.article_suffix_order
   WHERE a.law_id = v_law
     AND NOT EXISTS (SELECT 1 FROM article_versions v WHERE v.article_id = a.id)
  ON CONFLICT (article_id, version_no) DO NOTHING;
  GET DIAGNOSTICS v_ins_ver = ROW_COUNT;

  SELECT count(*) INTO v_cnt FROM articles a JOIN m250_art m ON m.article_no=a.article_no AND m.suffix=a.article_suffix_order
   WHERE a.law_id=v_law;
  IF v_cnt <> 111 THEN
    RAISE EXCEPTION '[250] عدد صفوف النص % بدل 111', v_cnt;
  END IF;
  SELECT count(*) INTO v_vcnt FROM article_versions v JOIN articles a ON a.id=v.article_id WHERE a.law_id=v_law;
  IF v_vcnt <> 111 THEN
    RAISE EXCEPTION '[250] عدد نسخ النص % بدل 111', v_vcnt;
  END IF;
  RAISE NOTICE '[250] قانون 111/1980: جديد=%, صفوف مضافة=%, نسخ مضافة=%', v_new_law, v_ins_art, v_ins_ver;
END
$m250$;
